var i=[{title:`Drücken gegenüber Ziehen`,text:`Liegestütze und Brustpressen betonen Brust, Trizeps und vordere Schultern. Rudern und Latzug betonen die Rückenmuskeln und die Ellbogenbeuger. Viele Schultermuskeln arbeiten bei beiden zusammen, die beiden Gruppen sind also nicht an jedem Gelenk oder in jeder Ebene genaue Gegensätze.`},{title:`Das Verhältnis 1:1`,text:`Eine ähnliche Zahl an wöchentlichen Druck- und Zugsätzen ist für Anfänger ein nützlicher Planungscheck. Es ist keine bewiesene Formel für Haltung oder Schultergesundheit. Was du brauchst, hängt von deiner Sportart, deinen Zielen, deiner Übungsauswahl und dem ab, was dein Körper verträgt. Ein Programm rund um das Bankdrücken kann mehr Rückenarbeit enthalten, und ein anderes stellt die Zugleistung an erste Stelle.`},{title:`Den Unterkörper ausgleichen`,text:`Dieselbe Idee gilt für die Beine: kniedominante Kniebeugen und Ausfallschritte werden mit hüftdominanten Hüftbeugen und Brücken kombiniert. Die Muskeln auf der Rück- und Vorderseite des Körpers brauchen keine identischen Satzzahlen. Ziel ist, jedes Muster abzudecken und über die Zeit Leistungsfähigkeit aufzubauen. Perfekte Symmetrie ist nicht das Ziel, und sie garantiert nicht, dass du dich nicht verletzt.`},{title:`Beispiel`,text:`Ein Ganzkörpertraining könnte Kurzhantel-Drücken mit gestütztem Rudern kombinieren und dann Beine und Rumpf trainieren. An einem anderen Tag könnte Überkopfdrücken mit Latzug kombiniert werden. So verteilst du horizontales und vertikales Drücken und Ziehen über die Woche, wenn deine Ausrüstung es erlaubt. Gleichmäßige Technik und passende Lasten zählen mehr als zueinander passende Übungsnamen.`},{title:`TrainUp nutzen`,text:`Jede Übungsseite unter „Übungen“ zeigt ihr Bewegungsmuster, sodass du sehen kannst, wie sich deine Woche zwischen Drücken und Ziehen aufteilt. Wenn das Drücken überwiegt und du keinen Grund dafür hast, füge eine Ruder- oder Zugvariante hinzu, die zu deiner Ausrüstung passt und deine Schulter-, Handgelenk- oder Lastgrenzen respektiert.`}];var t=[{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: Sicherheit und Grundlagen des Krafttrainings`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};